import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

min_sum = float('inf')
for r in range(8):
    sum_val = combinations(r, 3) + combinations(7 - r, 3)
    if sum_val < min_sum:
        min_sum = sum_val

