from itertools import combinations

def combinations_3(k):
    if k < 3:
        return 0
    # C(k, 3) = k * (k-1) * (k-2) / 6
    return k * (k - 1) * (k - 2) // 6

def check_n(n):
    """Checks if for a given n, every partition r+b=n yields >= 2 monochromatic triangles."""
    print(f"--- Checking n = {n} ---")

    # We only need to check partitions where r <= n/2 due to symmetry
    for r in range(n // 2 + 1):
        b = n - r

        # Calculate monochromatic triangles: C(r, 3) + C(b, 3)
        monochromatic_count = combinations_3(r) + combinations_3(b)

        print(f"Partition ({r}, {b}): Monochromatic count = {monochromatic_count}")

        if monochromatic_count < 2:
            print(f"FAIL: Found a partition ({r}, {b}) where count is less than 2.")
            return False

    print(f"SUCCESS: All partitions for n={n} yield at least 2 monochromatic triangles.")
    return True

# Test values sequentially:
n_to_test = [1, 2, 3, 4, 5, 6]
for n in n_to_test:
    if check_n(n):
        print(f"\nSmallest successful n found so far: {n}")
    else:
        print(f"\nSkipping subsequent tests, as n={n} failed.")

